from dataclasses import dataclass, field
from typing import Dict, List, Optional, Any, Tuple, Iterable

# Constants
SKIPPED = 'skipped'
PASSED = 'passed'
FAILED = 'failed'
DEFAULT_PENALTY_PER_GATE = 6.25
DEFAULT_TIMEOUT_S = 60

# Dependency contract: hae/evaluation/artifacts.py
# Since it is being implemented in parallel, we assume it exists or provide a fallback if needed.
# However, the prompt says "being implemented in parallel", implying we should import it.
# If it's not available, we might need a local fallback or assume it's in the path.
# Given the strict API contract, I will import it. If it fails, the harness might fail,
# but usually, these modules are co-located.
try:
    from hae.evaluation.artifacts import (
        is_generated_path,
        is_malformed_path,
        sanitize_path,
        filter_bundle,
        partition_bundle,
        count_source_files
    )
except ImportError:
    # Fallback implementation if artifacts.py is not yet available in the environment
    # This ensures the harness can run even if the dependency is slightly out of sync
    # during development/testing, though in production it should be present.

    EXCLUDED_DIR_SEGMENTS = ('.pytest_cache', '__pycache__', 'venv', '.venv', '.git', '.mypy_cache', '.ruff_cache', '.tox', 'node_modules', '.ipynb_checkpoints')
    EXCLUDED_DIR_SUFFIXES = ('.egg-info', '.dist-info')

    def is_generated_path(path: str) -> bool:
        parts = path.split(os.sep)
        for part in parts:
            if part in EXCLUDED_DIR_SEGMENTS:
                return True
            if any(part.endswith(s) for s in EXCLUDED_DIR_SUFFIXES):
                return True
        return False

    def is_malformed_path(path: str) -> bool:
        if not path:
            return True
        if path != path.strip():
            return True
        if '*' in path or '`' in path:
            return True
        if path.startswith('-'):
            return True
        if path.endswith('.') or path.endswith('~'):
            return True
        return False

    def sanitize_path(path: str) -> str:
        path = path.strip()
        path = path.replace('*', '').replace('`', '')
        if path.startswith('-'):
            path = path[1:]
        if path.endswith('.') or path.endswith('~'):
            path = path[:-1]
        return path

    def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
        return {k: v for k, v in bundle.items() if not is_generated_path(k) and not is_malformed_path(k)}

    def partition_bundle(bundle: Dict[str, str]) -> Tuple[Dict[str, str], Dict[str, str], Dict[str, str]]:
        authored = {}
        generated = {}
        malformed = {}
        for k, v in bundle.items():
            if is_generated_path(k):
                generated[k] = v
            elif is_malformed_path(k):
                malformed[k] = v
            else:
                authored[k] = v
        return authored, generated, malformed

    def count_source_files(bundle: Dict[str, str], suffixes: Iterable[str] = ('.py',)) -> int:
        count = 0
        for path in bundle:
            if not is_generated_path(path) and not is_malformed_path(path):
                if any(path.endswith(s) for s in suffixes):
                    count += 1
        return count


@dataclass
class GateResult:
    """Outcome of a single verification gate."""
    name: str
    status: str
    method: str
    detail: str = ''
    duration_s: float = 0.0
    evidence: Dict[str, Any] = field(default_factory=dict)

    @property
    def passed(self) -> bool:
        return self.status == PASSED

    @property
    def evaluated(self) -> bool:
        return self.status != SKIPPED


@dataclass
class VerificationReport:
    """Aggregate result across all gates."""
    gates: List[GateResult]
    score_penalty: float
    authored_files: int
    python_files: int
    source: str = 'bundle'
    harness_version: str = '3.0-execution'

    def gate(self, name: str) -> Optional[GateResult]:
        for g in self.gates:
            if g.name == name:
                return g
        return None

    @property
    def evaluated_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.evaluated]

    @property
    def passed_gates(self) -> List[GateResult]:
        return [g for g in self.gates if g.passed]

    @property
    def gate_status(self) -> Dict[str, str]:
        """Gate name -> PASSED | FAILED | SKIPPED. The fitness function's input."""
        return {g.name: g.status for g in self.gates}

    @property
    def gate_detail(self) -> Dict[str, str]:
        return {g.name: g.detail for g in self.gates}

    @property
    def pass_rate(self) -> float:
        """Fraction of *evaluated* gates that passed. Skips are excluded."""
        evaluated = self.evaluated_gates
        if not evaluated:
            return 0.0
        passed_count = sum(1 for g in evaluated if g.passed)
        return passed_count / len(evaluated)

    def summary(self) -> str:
        lines = [f"Verification Report ({self.source})"]
        lines.append(f"Authored Files: {self.authored_files}, Python Files: {self.python_files}")
        lines.append(f"Score Penalty: {self.score_penalty:.2f}")
        lines.append(f"Pass Rate: {self.pass_rate:.2%}")
        lines.append("-" * 40)
        for g in self.gates:
            status_icon = "✅" if g.passed else ("❌" if g.status == FAILED else "⏭️")
            lines.append(f"{status_icon} {g.name}: {g.status} ({g.method}) - {g.detail}")
        return "\n".join(lines)

    def to_dict(self) -> Dict[str, Any]:
        return {
            "gates": [
                {
                    "name": g.name,
                    "status": g.status,
                    "method": g.method,
                    "detail": g.detail,
                    "duration_s": g.duration_s,
                    "evidence": g.evidence
                }
                for g in self.gates
            ],
            "score_penalty": self.score_penalty,
            "authored_files": self.authored_files,
            "python_files": self.python_files,
            "source": self.source,
            "harness_version": self.harness_version,
            "pass_rate": self.pass_rate,
            "gate_status": self.gate_status
        }


def extract_code_blocks(text: str) -> Dict[str, str]:
    """Recovers a path->content map from fenced code blocks in a deliverable.

    A last resort, used only when a firm produced no live workspace. Only the
    contents of fenced blocks are returned; the surrounding prose is discarded
    and never reaches a gate.
    """
    # Regex to match fenced code blocks with optional language and optional filename hint
    # Common patterns:
    # ```python
    # ```path/to/file.py
    # ```python path/to/file.py
    # We need to be robust. Let's look for ``` followed by optional lang, then optional path.

    blocks = {}
    # Pattern: ```(lang)?(path)?\n(content)\n```
    # This is tricky because standard markdown doesn't support paths in fences.
    # However, agents often use:
    # ```python
    # # path: src/main.py
    # ...
    # ```
    # Or:
    # ```src/main.py
    # ...
    # ```

    # Let's try a regex that captures the fence header and content.
    # Fence header: ``` followed by non-newline chars until newline.
    # Content: everything until next ```

    pattern = r"```([^\n]*)\n(.*?)\n```"
    matches = re.finditer(pattern, text, re.DOTALL)

    for match in matches:
        header = match.group(1).strip()
        content = match.group(2)

        # Try to extract path from header
        # If header looks like a path (contains / or .py etc), use it.
        # If header is just a language, we might need to look for a comment inside.

        path = None
        if header:
            # Check if header contains a path-like string
            # Simple heuristic: if it ends in .py or contains /
            parts = header.split()
            for part in parts:
                if part.endswith('.py') or '/' in part:
                    path = part
                    break

        if not path:
            # Look for "# path: ..." or "# file: ..." in the first few lines of content
            lines = content.split('\n')
            for line in lines[:5]:
                line = line.strip()
                if line.startswith('#'):
                    # Check for path hints
                    if 'path:' in line.lower():
                        path = line.split(':', 1)[1].strip()
                    elif 'file:' in line.lower():
                        path = line.split(':', 1)[1].strip()
                    elif line.lower().startswith('# path'):
                        path = line[6:].strip()
                    elif line.lower().startswith('# file'):
                        path = line[5:].strip()
                if path:
                    break

        if not path:
            # Generate a dummy path if none found, to avoid collision
            path = f"extracted_block_{len(blocks)}.py"

        # Sanitize path
        path = sanitize_path(path)
        if not path:
            path = f"extracted_block_{len(blocks)}.py"

        # If path already exists, append a counter to avoid overwriting
        if path in blocks:
            base, ext = os.path.splitext(path)
            path = f"{base}_{len(blocks)}{ext}"

        blocks[path] = content

    return blocks


class ExecutionHarness:
    """Materializes a workspace bundle and verifies it by actually running it."""

    def __init__(self, timeout_s: int = DEFAULT_TIMEOUT_S, penalty_per_gate: float = DEFAULT_PENALTY_PER_GATE, python_executable: Optional[str] = None):
        self.timeout_s = timeout_s
        self.penalty_per_gate = penalty_per_gate
        self.python_executable = python_executable or sys.executable

    def verify_workspace(self, workspace: Any = None, deliverable_text: str = '') -> VerificationReport:
        """Verifies whatever code a firm actually produced.

        This is the entry point tournaments use. A firm normally writes into a
        live `AgentWorkspace`; if it never did, we fall back to the fenced code
        blocks embedded in its written deliverable.

        `deliverable_text` is *only* mined for code blocks. Its prose is never
        passed to a gate, because the entire point of this harness is that an
        essay about OpenTelemetry cannot satisfy the telemetry gate.
        """
        bundle = {}
        source = 'bundle'

        if workspace is not None:
            # Assume workspace has a method to get files or is a dict
            if hasattr(workspace, 'get_files'):
                bundle = workspace.get_files()
            elif isinstance(workspace, dict):
                bundle = workspace
            else:
                # Try to treat as directory
                if os.path.isdir(str(workspace)):
                    return self.verify_directory(str(workspace))
                else:
                    # Fallback to deliverable text
                    bundle = extract_code_blocks(deliverable_text)
                    source = 'deliverable'
        else:
            bundle = extract_code_blocks(deliverable_text)
            source = 'deliverable'

        return self.verify_bundle(bundle, source=source)

    def verify_bundle(self, bundle: Dict[str, str], source: str = 'bundle') -> VerificationReport:
        """Verifies an in-memory path->content map by writing it to a temp dir."""
        # Filter bundle to remove generated/malformed paths
        authored_bundle = filter_bundle(bundle)

        # Count files
        authored_files = len(authored_bundle)
        python_files = count_source_files(authored_bundle, suffixes=('.py',))

        # Create temp dir
        with tempfile.TemporaryDirectory() as tmpdir:
            # Write files
            for path, content in authored_bundle.items():
                full_path = os.path.join(tmpdir, path)
                os.makedirs(os.path.dirname(full_path), exist_ok=True)
                with open(full_path, 'w', encoding='utf-8') as f:
                    f.write(content)

            return self.verify_directory(tmpdir, authored=authored_bundle, source=source)

    def verify_directory(self, workdir: str, authored: Optional[Dict[str, str]] = None, source: str = 'directory') -> VerificationReport:
        """Verifies an existing workspace directory."""
        if authored is None:
            # Scan directory
            bundle = {}
            for root, dirs, files in os.walk(workdir):
                # Prune excluded dirs
                dirs[:] = [d for d in dirs if not is_generated_path(os.path.relpath(os.path.join(root, d), workdir))]

                for file in files:
                    rel_path = os.path.relpath(os.path.join(root, file), workdir)
                    if not is_generated_path(rel_path) and not is_malformed_path(rel_path):
                        full_path = os.path.join(root, file)
                        try:
                            with open(full_path, 'r', encoding='utf-8') as f:
                                bundle[rel_path] = f.read()
                        except Exception:
                            pass
            authored = bundle

        authored_files = len(authored)
        python_files = count_source_files(authored, suffixes=('.py',))

        gates = []

        # 1. Syntax Gate
        gates.append(self._gate_syntax(workdir, authored))

        # 2. Build Gate
        gates.append(self._gate_build(workdir, authored))

        # 3. Smoke Gate
        gates.append(self._gate_smoke(workdir, authored))

        # 4. Tests Gate
        gates.append(self._gate_tests(workdir, authored))

        # 5. Telemetry Gate
        gates.append(self._gate_telemetry(workdir, authored))

        # Calculate penalty
        failed_count = sum(1 for g in gates if g.status == FAILED)
        score_penalty = failed_count * self.penalty_per_gate

        return VerificationReport(
            gates=gates,
            score_penalty=score_penalty,
            authored_files=authored_files,
            python_files=python_files,
            source=source
        )

    def _gate_syntax(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start_time = time.time()
        method = "ast.parse"
        py_files = [p for p in authored if p.endswith('.py')]

        if not py_files:
            return GateResult(
                name="syntax",
                status=FAILED,
                method=method,
                detail="No Python files found.",
                duration_s=time.time() - start_time
            )

        errors = []
        for path in py_files:
            content = authored[path]
            try:
                ast.parse(content)
            except SyntaxError as e:
                errors.append(f"{path}: {e}")

        if errors:
            return GateResult(
                name="syntax",
                status=FAILED,
                method=method,
                detail="Syntax errors found: " + "; ".join(errors),
                duration_s=time.time() - start_time
            )

        return GateResult(
            name="syntax",
            status=PASSED,
            method=method,
            detail=f"All {len(py_files)} Python files parsed successfully.",
            duration_s=time.time() - start_time
        )

    def _gate_build(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start_time = time.time()
        method = "pip install -e ."

        # Check for packaging metadata
        has_pyproject = 'pyproject.toml' in authored
        has_setup_py = 'setup.py' in authored
        has_setup_cfg = 'setup.cfg' in authored

        if not (has_pyproject or has_setup_py or has_setup_cfg):
            return GateResult(
                name="build",
                status=FAILED,
                method=method,
                detail="No packaging metadata (pyproject.toml, setup.py, setup.cfg) found.",
                duration_s=time.time() - start_time
            )

        if has_pyproject:
            try:
                with open(os.path.join(workdir, 'pyproject.toml'), 'rb') as f:
                    data = tomllib.load(f)
                if not any(k in data for k in ['project', 'build-system', 'tool']):
                    return GateResult(
                        name="build",
                        status=FAILED,
                        method=method,
                        detail="pyproject.toml is valid TOML but missing required tables ([project], [build-system], or [tool]).",
                        duration_s=time.time() - start_time
                    )
            except Exception as e:
                return GateResult(
                    name="build",
                    status=FAILED,
                    method=method,
                    detail=f"pyproject.toml is invalid: {e}",
                    duration_s=time.time() - start_time
                )

        # Try to install
        try:
            # Check if pip is available
            subprocess.run([self.python_executable, "-m", "pip", "--version"], 
                           capture_output=True, timeout=10, check=True)
        except Exception:
            return GateResult(
                name="build",
                status=SKIPPED,
                method=method,
                detail="pip not available or failed to run.",
                duration_s=time.time() - start_time
            )

        try:
            # Run pip install
            result = subprocess.run(
                [self.python_executable, "-m", "pip", "install", "-e", ".", "--no-deps", "--no-build-isolation"],
                cwd=workdir,
                capture_output=True,
                text=True,
                timeout=self.timeout_s
            )
            if result.returncode != 0:
                return GateResult(
                    name="build",
                    status=FAILED,
                    method=method,
                    detail=f"pip install failed: {result.stderr}",
                    duration_s=time.time() - start_time
                )
        except subprocess.TimeoutExpired:
            return GateResult(
                name="build",
                status=FAILED,
                method=method,
                detail="pip install timed out.",
                duration_s=time.time() - start_time
            )
        except Exception as e:
            return GateResult(
                name="build",
                status=FAILED,
                method=method,
                detail=f"pip install error: {e}",
                duration_s=time.time() - start_time
            )

        return GateResult(
            name="build",
            status=PASSED,
            method=method,
            detail="Package installed successfully.",
            duration_s=time.time() - start_time
        )

    def _gate_smoke(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start_time = time.time()
        method = "subprocess import"

        # Find non-test modules
        # Exclude test files
        modules = []
        for path in authored:
            if not path.endswith('.py'):
                continue
            basename = os.path.basename(path).lower()
            if 'test' in basename:
                continue
            # Convert path to module name
            # Remove .py
            mod_path = path[:-3]
            # Replace / with .
            mod_name = mod_path.replace('/', '.').replace('\\', '.')
            # Handle __init__.py
            if mod_name.endswith('.__init__'):
                mod_name = mod_name[:-9]
            if not mod_name:
                continue
            modules.append(mod_name)

        if not modules:
            return GateResult(
                name="smoke",
                status=FAILED,
                method=method,
                detail="No importable non-test modules found.",
                duration_s=time.time() - start_time
            )

        # Prepare PYTHONPATH
        src_dir = os.path.join(workdir, "src")
        env = os.environ.copy()
        current_pythonpath = env.get('PYTHONPATH', '')
        new_paths = [workdir, src_dir]
        if current_pythonpath:
            new_paths.append(current_pythonpath)
        env['PYTHONPATH'] = os.pathsep.join(new_paths)

        # Try to import each module
        failed_modules = []
        skipped_modules = []

        for mod_name in modules:
            try:
                # Run a subprocess to import
                code = f"import {mod_name}"
                result = subprocess.run(
                    [self.python_executable, "-c", code],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )
                if result.returncode != 0:
                    stderr = result.stderr
                    if "ModuleNotFoundError" in stderr:
                        # Check if it's a third-party package
                        # If the module itself is not found, it's a failure.
                        # If a dependency is not found, it's skipped.
                        # We need to distinguish.
                        # If the error is "No module named 'mod_name'", it's a failure.
                        # If it's "No module named 'dep'", it's skipped.
                        if f"No module named '{mod_name}'" in stderr or f"No module named \"{mod_name}\"" in stderr:
                            failed_modules.append(mod_name)
                        else:
                            skipped_modules.append(mod_name)
                    else:
                        failed_modules.append(mod_name)
            except Exception:
                failed_modules.append(mod_name)

        if failed_modules:
            return GateResult(
                name="smoke",
                status=FAILED,
                method=method,
                detail=f"Failed to import modules: {', '.join(failed_modules)}",
                duration_s=time.time() - start_time
            )

        if skipped_modules and not failed_modules:
            # If all modules were skipped due to missing deps, return SKIPPED
            if len(skipped_modules) == len(modules):
                return GateResult(
                    name="smoke",
                    status=SKIPPED,
                    method=method,
                    detail=f"Modules skipped due to missing dependencies: {', '.join(skipped_modules)}",
                    duration_s=time.time() - start_time
                )

        return GateResult(
            name="smoke",
            status=PASSED,
            method=method,
            detail=f"All {len(modules)} modules imported successfully.",
            duration_s=time.time() - start_time
        )

    def _gate_tests(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start_time = time.time()
        method = "pytest"

        # Find test files
        test_files = []
        for path in authored:
            if not path.endswith('.py'):
                continue
            basename = os.path.basename(path).lower()
            if 'test' in basename:
                test_files.append(path)

        if not test_files:
            return GateResult(
                name="tests",
                status=FAILED,
                method=method,
                detail="No test files found.",
                duration_s=time.time() - start_time
            )

        # Prepare PYTHONPATH
        src_dir = os.path.join(workdir, "src")
        env = os.environ.copy()
        current_pythonpath = env.get('PYTHONPATH', '')
        new_paths = [workdir, src_dir]
        if current_pythonpath:
            new_paths.append(current_pythonpath)
        env['PYTHONPATH'] = os.pathsep.join(new_paths)

        # Check if pytest is installed
        try:
            subprocess.run([self.python_executable, "-m", "pytest", "--version"], 
                           capture_output=True, timeout=10, check=True)
            has_pytest = True
        except Exception:
            has_pytest = False

        if has_pytest:
            try:
                result = subprocess.run(
                    [self.python_executable, "-m", "pytest", "-v", "--tb=short"],
                    cwd=workdir,
                    env=env,
                    capture_output=True,
                    text=True,
                    timeout=self.timeout_s
                )
                if result.returncode != 0:
                    # Check if it's a collection error due to missing deps
                    if "ModuleNotFoundError" in result.stderr or "ModuleNotFoundError" in result.stdout:
                        return GateResult(
                            name="tests",
                            status=SKIPPED,
                            method=method,
                            detail="Tests skipped due to missing dependencies.",
                            duration_s=time.time() - start_time
                        )
                    return GateResult(
                        name="tests",
                        status=FAILED,
                        method=method,
                        detail=f"Tests failed: {result.stdout[-500:]}",
                        duration_s=time.time() - start_time
                    )
                return GateResult(
                    name="tests",
                    status=PASSED,
                    method=method,
                    detail="All tests passed.",
                    duration_s=time.time() - start_time
                )
            except subprocess.TimeoutExpired:
                return GateResult(
                    name="tests",
                    status=FAILED,
                    method=method,
                    detail="Tests timed out.",
                    duration_s=time.time() - start_time
                )
            except Exception as e:
                return GateResult(
                    name="tests",
                    status=FAILED,
                    method=method,
                    detail=f"Pytest error: {e}",
                    duration_s=time.time() - start_time
                )
        else:
            # Stdlib fallback
            method = "unittest fallback"
            # We need to run a script that imports each test file and collects/executes tests
            # This is complex to do in a single subprocess call without writing a temp script.
            # Let's write a temp script.

            script_content = """
import sys
import os
import unittest
import importlib.util

def run_tests(test_files):
    loader = unittest.TestLoader()
    suite = unittest.TestSuite()

    for test_file in test_files:
        try:
            spec = importlib.util.spec_from_file_location("test_module", test_file)
            module = importlib.util.module_from_spec(spec)
            spec.loader.exec_module(module)

            # Collect unittest.TestCase subclasses
            for name in dir(module):
                obj = getattr(module, name)
                if isinstance(obj, type) and issubclass(obj, unittest.TestCase) and obj is not unittest.TestCase:
                    suite.addTests(loader.loadTestsFromTestCase(obj))

            # Collect bare test_* functions
            for name in dir(module):
                if name.startswith('test_'):
                    obj = getattr(module, name)
                    if callable(obj) and not isinstance(obj, type):
                        # Check if it takes 0 required args
                        import inspect
                        sig = inspect.signature(obj)
                        params = [p for p in sig.parameters.values() if p.default is inspect.Parameter.empty]
                        if len(params) == 0:
                            suite.addTest(unittest.FunctionTestCase(obj))
        except ModuleNotFoundError as e:
            print(f"SKIP: {test_file} - {e}")
            sys.exit(2) # Special exit code for skip
        except Exception as e:
            print(f"ERROR: {test_file} - {e}")
            sys.exit(1)

    runner = unittest.TextTestRunner(verbosity=2)
    result = runner.run(suite)

    if result.wasSuccessful():
        sys.exit(0)
