    def _gate_telemetry(self, workdir: str, authored: Dict[str, str]) -> GateResult:
        start_time = time.time()
        method = "AST analysis"

        py_files = [p for p in authored if p.endswith('.py')]

        has_import = False
        has_call = False

        tracer_methods = {
            'start_as_current_span', 'start_span', 'get_tracer', 
            'get_tracer_provider', 'set_tracer_provider', 'get_meter'
        }

        for path in py_files:
            content = authored[path]
            try:
                tree = ast.parse(content)
            except SyntaxError:
                continue

            for node in ast.walk(tree):
                # Check for import opentelemetry or from opentelemetry ... import ...
                if isinstance(node, ast.Import):
                    for alias in node.names:
                        if alias.name == 'opentelemetry' or alias.name.startswith('opentelemetry.'):
                            has_import = True
                elif isinstance(node, ast.ImportFrom):
                    if node.module == 'opentelemetry' or (node.module and node.module.startswith('opentelemetry.')):
                        has_import = True

                # Check for calls to tracer/span methods
                if isinstance(node, ast.Call):
                    func = node.func
                    if isinstance(func, ast.Attribute):
                        if func.attr in tracer_methods:
                            has_call = True
                    elif isinstance(func, ast.Name):
                        if func.id in tracer_methods:
                            has_call = True

        if not has_import:
            return GateResult(
                name="telemetry",
                status=FAILED,
                method=method,
                detail="No import of opentelemetry found.",
                duration_s=time.time() - start_time
            )

        if not has_call:
            return GateResult(
                name="telemetry",
                status=FAILED,
                method=method,
                detail="No calls to tracer/span methods found.",
                duration_s=time.time() - start_time
            )

